(()=>{
  window.__err=[];
  window.addEventListener('error',(ev)=>{ window.__err.push({msg:ev.message, stack:(ev.error&&ev.error.stack)||'', at:window.__echoes.tick, phase:(window.__echoes.cmd('runState')||{}).phase}); });
  const E=window.__echoes;
  const seen=new Set(); const log=[];
  const st={trace:[],lastPhase:null,lastRoom:null,guard:0,log,seen};
  st.collect=()=>{ for(const e of E.events){ if(!seen.has(e)){ seen.add(e); log.push(e); } } };
  st.snap=(v)=>({room:v.room,phase:v.phase,mode:v.mode,wallet:v.wallet,free:v.freeSkillSlots,tick:E.tick,
    reward:v.reward?{t:v.reward.type,id:v.reward.id,prom:v.reward.promised,sub:v.reward.substituted,line:v.reward.line}:null,
    path:v.path?v.path.options.map(o=>o.win+'/'+o.reward):null,
    shop:v.shop?v.shop.stock.map(s=>s.node+':'+s.price+':'+(s.affordable?'aff':'no')):null});
  st.tick=()=>{
    st.collect();
    const v=E.cmd('runState');
    if(v.phase!==st.lastPhase||v.room!==st.lastRoom){ st.trace.push(st.snap(v)); st.lastPhase=v.phase; st.lastRoom=v.room; }
    if(v.phase==='victory'||v.phase==='defeat') return false;
    try{
      if(v.phase==='combat'){ if(v.room===8) E.cmd('killBoss'); else E.cmd('killAllEnemies'); }
      else if(v.phase==='reward'){ E.cmd('draftTake'); }
      else if(v.phase==='path'){ E.cmd('pathChoose',0); }
      else if(v.phase==='shop'){ E.cmd('shopBuy',0); E.cmd('shopAdvance'); }
    }catch(e){ st.trace.push({cmdError:String(e), phase:v.phase, room:v.room}); }
    return true;
  };
  st.run=async(ms)=>{ const t0=Date.now(); while(Date.now()-t0<ms){ if(!st.tick()) return 'done'; await new Promise(r=>setTimeout(r,120)); } return 'more'; };
  window.__drv=st;
  E.cmd('startRun');
  return 'installed';
})()

